import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Perf thresholds — SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"quality/perf-thresholds.md","filePath":"quality/perf-thresholds.md"}'),s={name:"quality/perf-thresholds.md"};function i(r,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="perf-thresholds-—-ssot" tabindex="-1">Perf thresholds — SSOT <a class="header-anchor" href="#perf-thresholds-—-ssot" aria-label="Permalink to &quot;Perf thresholds — SSOT&quot;">​</a></h1><h2 id="why-this-file-exists" tabindex="-1">Why this file exists <a class="header-anchor" href="#why-this-file-exists" aria-label="Permalink to &quot;Why this file exists&quot;">​</a></h2><p>The previous perf-harness rollout (v1.13-1 / v1.14-1) picked p95 thresholds by feel — <code>20ms</code> for realtime, <code>40ms</code> for AI-LLM mocks, <code>50ms</code> for dogfood adapter joins. Those numbers had no external justification, so a passing report proved nothing beyond &quot;the mock is not catastrophically slow&quot;.</p><p>This doc pins <strong>every</strong> perf threshold in kiwa to one of three grounded rationales:</p><ol><li><strong>Provider SLA</strong> — the third-party API kiwa mocks documents its own p99 latency. The kiwa threshold sits at or under that so a passing mock behaves at least as fast as the real thing.</li><li><strong>Human-perception target</strong> — for user-facing SaaS surfaces (chat, cursor, notification), Jakob Nielsen&#39;s classic thresholds apply: 100 ms feels instant, 1 s keeps flow, 10 s loses users. Kiwa targets the strictest applicable band.</li><li><strong>Mock-invariant</strong> — a mock is in-memory code. Its perf floor is the JS engine&#39;s own event-loop tick + heap allocation cost. When a mock&#39;s p95 exceeds this floor by more than one order of magnitude, something is architecturally wrong (e.g. accidentally awaiting a promise chain per call). Kiwa targets &lt; 10 × the JS floor.</li></ol><h2 id="threshold-table" tabindex="-1">Threshold table <a class="header-anchor" href="#threshold-table" aria-label="Permalink to &quot;Threshold table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Op</th><th>p95 threshold</th><th>Rationale</th></tr></thead><tbody><tr><td><code>@kiwa/quality-metrics</code></td><td><code>evaluateReleaseGate</code></td><td>5 ms</td><td>mock-invariant (pure calculation, one heap object per call)</td></tr><tr><td><code>@kiwa/quality-metrics</code></td><td><code>diffReports</code></td><td>5 ms</td><td>mock-invariant</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td><code>anthropic.messages.create</code> (mock)</td><td>40 ms</td><td>provider SLA — Anthropic Messages p95 non-streaming is ~600ms; mock must be &lt; 10 % of live so tests do not become the bottleneck</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td><code>openai.chat.completions.create</code> (mock)</td><td>40 ms</td><td>provider SLA — OpenAI Chat Completions p95 is ~500-1200ms depending on model; same 10 % rule</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td><code>vercel.generateText</code> (mock)</td><td>40 ms</td><td>provider SLA — proxies to Anthropic / OpenAI, same target</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td><code>langchain.invoke</code> (mock)</td><td>40 ms</td><td>provider SLA — same</td></tr><tr><td><code>@kiwa/realtime</code></td><td><code>supabase.channel.track</code> (mock)</td><td>20 ms</td><td>mock-invariant (channel registry lookup + presence Map insert)</td></tr><tr><td><code>@kiwa/realtime</code></td><td><code>ably.channel.publish</code> (mock)</td><td>20 ms</td><td>mock-invariant</td></tr><tr><td><code>@kiwa/realtime</code></td><td><code>pusher.subscribeChannel</code> (mock)</td><td>20 ms</td><td>mock-invariant</td></tr><tr><td><code>@kiwa/realtime</code></td><td><code>socketio.emit</code> (mock)</td><td>20 ms</td><td>mock-invariant</td></tr><tr><td><code>@kiwa/payment</code></td><td><code>signWebhook</code> (mock)</td><td>10 ms</td><td>mock-invariant (HMAC-SHA256 over ~500 bytes is &lt; 1 ms on modern hardware)</td></tr><tr><td><code>@kiwa/payment</code></td><td><code>verifyWebhook</code> (mock)</td><td>10 ms</td><td>mock-invariant</td></tr><tr><td><code>@kiwa/search</code></td><td><code>search</code> on 20-doc index (mock)</td><td>5 ms</td><td>mock-invariant (linear scan over 20 docs)</td></tr><tr><td><code>dogfood-anthropic-chatbot</code></td><td><code>reply</code> (mock mode)</td><td>30 ms</td><td>mock-invariant + one @kiwa/ai-llm call ⇒ threshold matches ai-llm + adapter overhead budget</td></tr><tr><td><code>dogfood-anthropic-chatbot</code></td><td><code>replyStream</code> (mock mode)</td><td>50 ms</td><td>mock-invariant + streaming chunk fan-out (~5 chunks) ⇒ 5 × single-call budget</td></tr><tr><td><code>dogfood-anthropic-chatbot</code></td><td><code>toolLoop</code> (mock mode)</td><td>100 ms</td><td>mock-invariant + tool loop up to 5 iterations</td></tr><tr><td><code>dogfood-openai-tool-agent</code></td><td><code>validateToolSchemas</code></td><td>50 ms</td><td>mock-invariant (JSON Schema validate over 3 tools)</td></tr><tr><td><code>dogfood-openai-tool-agent</code></td><td><code>runToolLoop</code></td><td>100 ms</td><td>tool loop up to 5 iterations, matches Anthropic loop budget</td></tr><tr><td><code>dogfood-openai-tool-agent</code></td><td><code>runParallelToolCall</code></td><td>100 ms</td><td>2 parallel tools + finaliser turn</td></tr><tr><td><code>dogfood-vercel-ai-rag</code></td><td><code>embed</code> (mock)</td><td>20 ms</td><td>mock-invariant (hashing embedder)</td></tr><tr><td><code>dogfood-vercel-ai-rag</code></td><td><code>retrieve</code> (mock)</td><td>30 ms</td><td>mock-invariant + cosine similarity over ~5 docs</td></tr><tr><td><code>dogfood-vercel-ai-rag</code></td><td><code>answer</code> (mock)</td><td>100 ms</td><td>retrieve + LLM call budget</td></tr><tr><td><code>dogfood-supabase-realtime-chat</code></td><td><code>joinRoom</code></td><td>50 ms</td><td>Nielsen &quot;instant&quot; — chat presence must feel snappy</td></tr><tr><td><code>dogfood-supabase-realtime-chat</code></td><td><code>sendMessage</code></td><td>30 ms</td><td>Nielsen &quot;instant&quot; tightened — message send is on the critical hot path</td></tr><tr><td><code>dogfood-supabase-realtime-chat</code></td><td><code>getPresence</code></td><td>30 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-supabase-realtime-chat</code></td><td><code>sendTyping</code></td><td>100 ms</td><td>typing debounce absorbs 500 ms; single-call p95 has more headroom</td></tr><tr><td><code>dogfood-ably-collab-cursor</code></td><td><code>joinBoard</code></td><td>50 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-ably-collab-cursor</code></td><td><code>moveCursor</code></td><td>100 ms</td><td>60 fps throttle window is 16 ms; single call inside the throttle allowed 100 ms because it burst-fires</td></tr><tr><td><code>dogfood-ably-collab-cursor</code></td><td><code>rewindHistory</code></td><td>30 ms</td><td>in-memory ring buffer scan</td></tr><tr><td><code>dogfood-ably-collab-cursor</code></td><td><code>getPresence</code></td><td>30 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-socketio-notification</code></td><td><code>subscribeRoom</code></td><td>50 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-socketio-notification</code></td><td><code>deliverNotification</code></td><td>30 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-socketio-notification</code></td><td><code>getPending</code></td><td>30 ms</td><td>Nielsen &quot;instant&quot;</td></tr><tr><td><code>dogfood-socketio-notification</code></td><td><code>simulateReconnect</code></td><td>100 ms</td><td>reconnect ceremony (disconnect + queue drain + reconnect)</td></tr><tr><td><code>@kiwa/core</code></td><td><code>parseSpec</code></td><td>5 ms</td><td>mock-invariant (linear scan over meta lines + one table walk)</td></tr><tr><td><code>@kiwa/core</code></td><td><code>createPool</code> (size 4)</td><td>5 ms</td><td>mock-invariant (Promise.all fan-out over 4 acquires + one borrow/release)</td></tr><tr><td><code>@kiwa/dapp</code></td><td><code>eventEmitterEmit</code></td><td>5 ms</td><td>mock-invariant (node:events dispatch + listener count)</td></tr><tr><td><code>@kiwa/dapp</code></td><td><code>anvilKeyLookup</code></td><td>5 ms</td><td>mock-invariant (readonly array indexing)</td></tr><tr><td><code>@kiwa/api</code></td><td><code>requestClientGet</code></td><td>5 ms</td><td>mock-invariant (url join + Response snapshot with stub fetcher)</td></tr><tr><td><code>@kiwa/api</code></td><td><code>requestClientPost</code></td><td>5 ms</td><td>mock-invariant (adds JSON.stringify encode over the GET path)</td></tr><tr><td><code>@kiwa/ui</code></td><td><code>setupComponentEnvSnapshot</code></td><td>30 ms</td><td>jsdom mount + React render + innerHTML capture — the lightest UI test path</td></tr><tr><td><code>@kiwa/ui</code></td><td><code>setupComponentEnvRender</code></td><td>30 ms</td><td>same jsdom + React mount cost baseline as snapshot</td></tr><tr><td><code>@kiwa/data</code></td><td><code>queueSend</code></td><td>5 ms</td><td>mock-invariant (dedup Set lookup + array push + consumer notify)</td></tr><tr><td><code>@kiwa/data</code></td><td><code>fakeClockAdvance</code></td><td>5 ms</td><td>mock-invariant (walk 2-entry cron table + fire due callbacks)</td></tr><tr><td><code>@kiwa/cli-test</code></td><td><code>writeFile</code></td><td>20 ms</td><td>fs write syscall + relative path resolution over an isolated tempdir</td></tr><tr><td><code>@kiwa/cli-test</code></td><td><code>readFile</code></td><td>10 ms</td><td>fs read syscall over an isolated tempdir</td></tr><tr><td><code>@kiwa/observability</code></td><td><code>collectRunHistory</code></td><td>5 ms</td><td>O(N) walk + per-test cap map over 200 records</td></tr><tr><td><code>@kiwa/observability</code></td><td><code>detectFlaky</code></td><td>5 ms</td><td>O(N) aggregation over 200 records</td></tr><tr><td><code>@kiwa/observability</code></td><td><code>checkThresholds</code></td><td>5 ms</td><td>mock-invariant (fixed 4-metric compare)</td></tr><tr><td><code>@kiwa/observability</code></td><td><code>renderDashboard</code></td><td>5 ms</td><td>markdown string concat over a 200-record summary</td></tr><tr><td><code>@kiwa/e2e</code></td><td><code>fetchOverLoopback</code></td><td>20 ms</td><td>node http server dispatch + fetch-handler adapter over loopback (no network)</td></tr><tr><td><code>@kiwa/cli</code></td><td><code>runSpecToTest</code></td><td>20 ms</td><td>md read + parseSpec + template render + file write</td></tr></tbody></table><h2 id="regression-detection-defaults" tabindex="-1">Regression detection defaults <a class="header-anchor" href="#regression-detection-defaults" aria-label="Permalink to &quot;Regression detection defaults&quot;">​</a></h2><p>Threshold: <strong>20 % p95 delta</strong> vs stored baseline (<code>.perf-baseline/{module}.json</code>), with Welch t-test for significance (t &gt; 2 ⇒ significant).</p><ul><li>baseline is created automatically on the first run (no <code>--baseline</code> flag needed since v1.14-post)</li><li>subsequent runs compare against baseline; a &gt; 20 % p95 increase with significant t-value fails the gate</li><li>to intentionally accept the new baseline (e.g. after a deliberate optimisation regression), delete <code>.perf-baseline/{module}.json</code> and rerun</li></ul><h2 id="real-api-measurement-mode" tabindex="-1">Real-API measurement mode <a class="header-anchor" href="#real-api-measurement-mode" aria-label="Permalink to &quot;Real-API measurement mode&quot;">​</a></h2><p>Live-mode perf tests coexist with mock perf tests under <code>tests/perf/</code>. The <code>*.live.perf.ts</code> files use <code>runPerf3LayerLive</code> from <code>@kiwa/perf-harness</code> and declare their required env vars via the <code>requiredEnv</code> option. Missing env vars trigger the skip path — the run still emits a report, but with <code>LIVE_ENV_MISSING</code> markers instead of gate results. This keeps CI-less environments honest: an empty report row is attributed to missing credentials, not silent success.</p><p>Enable live mode by setting the required env vars and rerunning the perf suite:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Live mode for one provider</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-anthropic-chatbot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:perf</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mock 3-layer runs alongside; live 3-layer runs against the real API</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># All 6 dogfood live envs</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-... OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-... \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SUPABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://... SUPABASE_ANON_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ABLY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... SOCKETIO_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://... \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  RAG_VECTOR_STORE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://... RAG_VECTOR_STORE_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:perf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --if-present</span></span></code></pre></div><p>Live iteration count defaults to 10 (vs 200 for mock) — live calls cost money and are slow, so a full pass fits in a coffee break. Concurrency defaults to 3 to avoid rate-limiting.</p><p>Live thresholds are provider-SLA sourced — not mock-invariant — and sit at the provider&#39;s own p95 target:</p><table tabindex="0"><thead><tr><th>provider</th><th>live p95 threshold</th><th>source</th></tr></thead><tbody><tr><td>Anthropic Messages (non-streaming)</td><td>1500 ms</td><td>Anthropic status page + latency dashboards</td></tr><tr><td>OpenAI Chat Completions (non-streaming, gpt-4o)</td><td>1500 ms</td><td>OpenAI status page</td></tr><tr><td>Supabase Realtime publish</td><td>250 ms</td><td>Supabase Realtime WebSocket round-trip target</td></tr><tr><td>Ably publish (round-trip)</td><td>200 ms</td><td>Ably SLA — 99.999 % delivery within 200 ms</td></tr><tr><td>Socket.io emit (loopback)</td><td>100 ms</td><td>in-cluster network + Redis adapter round-trip</td></tr></tbody></table><h2 id="concurrent-load-target" tabindex="-1">Concurrent load target <a class="header-anchor" href="#concurrent-load-target" aria-label="Permalink to &quot;Concurrent load target&quot;">​</a></h2><p>Every mock target has a serial baseline (concurrency = 1) and a concurrent stress run (concurrency = 10, iterations per worker = 50 ⇒ 500 samples). The concurrent p95 threshold is <strong>2 × the serial threshold</strong> — mocks share in-memory state (engines, recorders), so some contention is expected but &gt; 2 × means the shared state is a bottleneck.</p><h2 id="memory-delta-target" tabindex="-1">Memory delta target <a class="header-anchor" href="#memory-delta-target" aria-label="Permalink to &quot;Memory delta target&quot;">​</a></h2><p>Every mock op is checked for retained-heap growth. Threshold: <strong>&lt; 100 KB retained across 200 iterations</strong> (i.e. &lt; 500 bytes / call on average). Anything higher signals an unbounded internal Map / array / listener list.</p><h2 id="change-control" tabindex="-1">Change control <a class="header-anchor" href="#change-control" aria-label="Permalink to &quot;Change control&quot;">​</a></h2><p>If a threshold in the table changes, the PR body must document:</p><ol><li>Which threshold changed and by how much</li><li>Which of the 3 rationales (provider SLA / human perception / mock-invariant) still applies</li><li>If none apply, a new rationale row must be added to this file</li></ol><p>The rules/quality.md § test-passed marker gate forwards to this doc for perf assertions.</p>`,25)])])}const k=e(s,[["render",i]]);export{m as __pageData,k as default};
